package com.chx.claims.reporting.infra; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class ReportingRepository { private final JdbcTemplate jdbc; public ReportingRepository(JdbcTemplate j){jdbc=j;} public List<Map<String,Object>> statusSummary(){return jdbc.queryForList("select status, count(*) as count from claims group by status order by status");} public List<Map<String,Object>> workload(){return jdbc.queryForList("select assigned_officer_id, count(*) as count from claims where status not in ('SETTLED','REJECTED') group by assigned_officer_id");} public List<Map<String,Object>> exposure(){return jdbc.queryForList("select market, claim_type, currency, sum(claimed_amount) claimed_amount, sum(coalesce(reserve_amount,0)) reserve_amount, sum(coalesce(approved_amount,0)) approved_amount from claims where status not in ('SETTLED','REJECTED') group by market, claim_type, currency");} public List<Map<String,Object>> performance(){return jdbc.queryForList("select count(*) filter (where status in ('APPROVED','SETTLED','REJECTED')) as resolved_count, count(*) filter (where status not in ('APPROVED','SETTLED','REJECTED') and created_at < now() - interval '72 hours') as sla_breach_count from claims");} }
